  function projectPicker(){const {body,actions}=openEditor('Projects');for(const pr of p().projects){const row=el('div','list-row');row.append(button(pr.title,()=>{projectId=pr.id;level=2;closeEditor();render(true);},'grow link'),button('Edit',()=>entityEditor('projects',pr.id),'link'));body.append(row);}body.append(button('All RPM blocks',()=>{level=1;closeEditor();render(true);},'link'));actions.append(button('New project',()=>entityEditor('projects'),'primary'));}
