  async function aiAction(action,blockId=null){const startVersion=data().version,{body,actions}=openEditor(action==='sort'?'Sort into RPM blocks':action==='purpose'?'Purpose suggestion':'Goal ideas');const status=el('p','muted','Preparing a suggestion…');status.setAttribute('role','status');body.append(status);if(!api.getPhone().hasKey){status.textContent='Connect your AI key in Settings to get suggestions. Your plans stay saved.';actions.append(button('Settings',()=>api.native('settings'),'primary'));return;}
    try{
      if(action==='sort'){
        if(!api.sortPreview)throw new Error('Safe sorting previews are unavailable in this build.');
        const existing=await api.sortPreview.list();if(existing?.length){showSortPreview(existing[0],body,actions,'Review this saved suggestion. Nothing has moved yet.');return;}
      }
      const request=planningRequest(data(),action,blockId),prompt=JSON.parse(request.messages[1].content),selectedTaskIds=action==='sort'?prompt.context.tasks.map(task=>task.id):[];if(action==='sort'&&!selectedTaskIds.length){status.textContent='No unsorted active tasks to arrange. You can move tasks manually or capture something new.';return;}const response=await api.native('model',{body:request});if(response.status<200||response.status>=300)throw new Error('The AI request failed. Check your connection and try again.');const result=readPlanningResponse(response.body,action);if(data().version!==startVersion)throw new Error('Your plans changed while the AI was working. Ask again for a fresh suggestion.');if(!body.isConnected)return;status.textContent=action==='sort'?(result.explanation??'Proposed arrangement. Nothing has moved yet.'):result.text;
      if(action==='sort'){const assigned=new Set(result.blocks.flatMap(block=>block.taskIds??[])),leftUnsorted=selectedTaskIds.filter(id=>!assigned.has(id)),created=await api.sortPreview.create({id:globalThis.crypto?.randomUUID?.()??`sort-${Date.now()}-${Math.random().toString(36).slice(2)}`,selectedTaskIds,blocks:result.blocks,leftUnsorted});if(!body.isConnected)return;showSortPreview(created.preview,body,actions,result.explanation);}
      if(action==='purpose'){const b=p().blocks.find(x=>x.id===blockId);actions.append(button('Use purpose',()=>commit({type:'saveEntity',collection:'blocks',id:blockId,fields:{...b,purpose:result.text}}).catch(()=>{}),'primary'));}
    }catch(e){if(body.isConnected){status.textContent=e.message;status.className='error';}}
  }
